import 'dart:collection'; // For computing averages using Map entry values

class Transaction {
  final String coinName;
  final DateTime dateTime;
  final double profitLoss;

  Transaction(this.coinName, this.dateTime, this.profitLoss);
}

List<String> topThreeCoinsHighestAvgProfit(List<Transaction> transactions) {
  Map<String, double> coinAverages = {};

  for (Transaction transaction in transactions) {
    if (coinAverages.containsKey(transaction.coinName)) {
      coinAverages[transaction.coinName] += transaction.profitLoss;
    } else {
      coinAverages[transaction.coinName] = transaction.profitLoss;
    }
  }

  List<MapEntry<String, double>> sortedEntries = coinAverages.entries.toList()
    ..sort((a, b) => b.value.compareTo(a.value));

  return sortedEntries.take(3).map((e) => e.key).toList();
}

List<String> topThreeCoinsHighestAvgLoss(List<Transaction> transactions) {
  Map<String, double> coinAverages = {};

  for (Transaction transaction in transactions) {
    if (coinAverages.containsKey(transaction.coinName)) {
      coinAverages[transaction.coinName] =
          coinAverages[transaction.coinName]! + transaction.profitLoss;
    } else {
      coinAverages[transaction.coinName] = transaction.profitLoss;
    }
  }

  List<MapEntry<String, double>> sortedEntries = coinAverages.entries.toList()
    ..sort((a, b) => a.value.compareTo(b.value));

  return sortedEntries.takeLast(3).map((e) => e.key).toList();
}
```

